55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	const CURSE_SURCHARGE_RATE = 0.5;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
60	
61	const BASE_PREMIUMS: Record<string, number> = {
62	  sword: 100,
63	  amulet: 60,
64	  staff: 80,
65	  potion: 40,
66	  rune: 25,
67	  moonstone: 25,
68	};
69	
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const countByType = (items: Item[]): Map<string, number> => {
74	  const counts = new Map<string, number>();
75	  for (const item of items) {
76	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
77	  }
78	  return counts;
79	};
80	
81	const basePremiumOfGroup = (type: string, count: number): number =>
82	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
83	
84	const policyBasePremium = (items: Item[]): number =>
85	  [...countByType(items)].reduce(
86	    (total, [type, count]) => total + basePremiumOfGroup(type, count),
87	    0,
88	  );
89	
90	const firstInsuranceSurcharge = (policyBase: number): number =>
91	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
92	
93	const curseSurcharge = (item: Item): number =>
94	  item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : 0;
95	
96	const highEnchantmentSurcharge = (item: Item): number =>
97	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
98	    ? BASE_PREMIUMS[item.type] * HIGH_ENCHANTMENT_SURCHARGE_RATE
99	    : 0;
100	
101	const itemSurchargeTotal = (items: Item[]): number =>
102	  items.reduce(
103	    (total, item) => total + curseSurcharge(item) + highEnchantmentSurcharge(item),
104	    0,
105	  );
106	
107	const quote = (step: QuoteStep): QuoteResult => {
108	  const policyBase = policyBasePremium(step.items);
109	  const premiumBeforeRounding =
110	    policyBase +
111	    itemSurchargeTotal(step.items) +
112	    firstInsuranceSurcharge(policyBase) +
113	    PROCESSING_FEE;
114	  return { premium: Math.ceil(premiumBeforeRounding) };
115	};
116	
117	export const runScenario = (scenario: Scenario): ScenarioOutput => {
118	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
119	};
